fn run(input:&[u8],approved:bool){let d=tempfile::tempdir().unwrap();let cfg=d.path().join("rig");let script=d.path().join("script");std::fs::write(&script,"{\"tool\":\"exit_plan_mode\",\"args\":{\"plan\":\"# Fix parser\\nUse fixtures\"}}\n{\"tool\":\"get_goal\",\"args\":{}}\n").unwrap();std::fs::write(&cfg,format!("[plan]\nsection='Guide'\n[[models]]\nname='scripted'\ncommand=['/bin/sh','-c','HS_SEQMODEL_SCRIPT={} exec {}']\ndefault=true\n",script.display(),env!("CARGO_BIN_EXE_hs-plugin-scripted"))).unwrap();let log=d.path().join("run");let mut s=hs_loop::repl::ReplSession::load(&cfg,&log,false,Some(2)).unwrap();let mut editor=hs_loop::repl::StdinEditor::new(&log,std::io::Cursor::new(input));hs_loop::repl::run_interactive(&mut s,&mut editor).unwrap();assert_eq!(s.plan_view()["active"],!approved,"editor approval was not consumed by native review");let r=hs_log::StreamReader::open(&log,s.stream_id()).unwrap();let values:Vec<serde_json::Value>=r.events().unwrap().iter().filter_map(|e|serde_json::from_slice(&r.resolve_payload(e).ok()?).ok()).collect();assert_eq!(values.iter().any(|v|v["plugin"]=="exit_plan_mode"&&v["result"]["approved"]==true),approved);}

#[test]fn line_editor_review_uses_actual_next_line_as_explicit_answer(){run(b"/plan Fix parser\nApprove\n/quit\n",true)}
#[test]fn line_feedback_stays_in_plan_mode(){run(b"/plan Fix parser\nUse fixtures\n/quit\n",false)}
#[test]fn line_eof_dismisses_without_approval(){run(b"/plan Fix parser\n",false)}
